SELECT N.NOME, MAX(NULLIF(L.AUTOR, '')) AUTOR, MAX(L.TRECHO) TRECHO FROM LIVROS_NOMES N LEFT JOIN LIVROS_INDICADOS L ON L.TITULO COLLATE utf8mb4_0900_ai_ci = N.NOME WHERE N.ESTADO = 'PENDENTE' AND N.SUGESTAO_TITULO IS NULL AND N.CONFERIDO IS NULL GROUP BY N.ID, N.NOME ORDER BY COUNT(DISTINCT L.VIDEO_ID) DESC, N.ID LIMIT {{limit}}